INSERT IGNORE INTO screen_intro (id, screen_code, region, text_vi, audio_url, status, updated_at) VALUES
('DN-F02-BD-01', 'F-02', 'BD', 'Bến gỗ Bến Đò Ông Tư đang chờ từng chữ cái! Con ghép đúng chính tả để xếp hàng lên đò cùng bò nha!', NULL, 'draft', NOW()),
('DN-F02-BD-02', 'F-02', 'BD', 'Ông Tư chuẩn bị nhổ neo sang Cù Lao rồi! Con nghe từ và chọn từng chữ cái ghép cho chuẩn nhé!', NULL, 'draft', NOW()),
('DN-F02-BD-03', 'F-02', 'BD', 'Sương sớm phủ nhẹ mặt sông Bến Đò. Con nhìn nghĩa rồi ghép đủ chữ cái của từ cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F02-BD-04', 'F-02', 'BD', 'Mỗi chữ cái ghép đúng là thêm nhịp chèo cho chiếc đò. Cùng bò hoàn thành các từ mới hôm nay nhé!', NULL, 'draft', NOW()),
('DN-F02-TG-01', 'F-02', 'TG', 'Gió lộng trên cánh đồng Tháp Gió làm các chữ cái bay lơ lửng! Con chạm ghép lại thành từ đúng nha!', NULL, 'draft', NOW()),
('DN-F02-TG-02', 'F-02', 'TG', 'Mimi đứng dưới chân Tháp Gió cổ vũ con đấy! Nghe phát âm rồi chọn từng chữ cái ghép đúng nhé!', NULL, 'draft', NOW()),
('DN-F02-TG-03', 'F-02', 'TG', 'Owlbert trộn sẵn các chữ cái bên cánh quạt Tháp Gió. Con ghép chính tả thật gọn gàng cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F02-TG-04', 'F-02', 'TG', 'Storm vừa gửi sáu từ mới giữa làn gió Tháp Gió. Con chạm đúng thứ tự chữ cái cùng bò nhé!', NULL, 'draft', NOW()),
('DN-F02-VS-01', 'F-02', 'VS', 'Giữa Vườn Sữa xanh mát, cùng Cowdi nhìn hình và ghép từng chữ cái cho tròn chính tả nha!', NULL, 'draft', NOW()),
('DN-F02-VS-02', 'F-02', 'VS', 'Bamboo xếp sẵn bảng chữ cái bên rừng trúc Vườn Sữa. Con bấm loa nghe rồi ghép từ đúng nhé!', NULL, 'draft', NOW()),
('DN-F02-VS-03', 'F-02', 'VS', 'Đàn gà ở Vườn Sữa đang tò mò xem con ghép chữ đấy! Chọn đúng từng chữ cái cùng bò nha!', NULL, 'draft', NOW()),
('DN-F02-VS-04', 'F-02', 'VS', 'Bamboo Spirit gửi tặng con sáu từ quen ở Vườn Sữa. Chạm chữ cái ghép thành từ chuẩn cùng Cowdi nhé!', NULL, 'draft', NOW()),
('DN-F04-BD-01', 'F-04', 'BD', 'Chiếc đò ngang của ông Tư đã sẵn sàng bên bến gỗ! Nghe mẫu, đếm ba hai một rồi đọc to nhé!', NULL, 'draft', NOW()),
('DN-F04-BD-02', 'F-04', 'BD', 'Sương sớm trên mặt sông Bến Đò sẽ tan nhanh khi con đọc to, rõ từng câu tiếng Anh cùng bò nha!', NULL, 'draft', NOW()),
('DN-F04-BD-03', 'F-04', 'BD', 'Ông Tư khen ai phát âm rõ trên Bến Đò lắm! Con nghe kỹ câu mẫu rồi gọi pet qua sông nhé!', NULL, 'draft', NOW()),
('DN-F04-BD-04', 'F-04', 'BD', 'Đứng bên bến gỗ hướng sang Cù Lao, con nghe mẫu rồi tự tin nói to từng câu cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F04-TG-01', 'F-04', 'TG', 'Gió trên Tháp Gió thổi lộng lắm! Con nghe câu mẫu rồi đọc thật to để gọi pet vượt gió nha!', NULL, 'draft', NOW()),
('DN-F04-TG-02', 'F-04', 'TG', 'Mimi và Owlbert đang lắng nghe con dưới chân Tháp Gió. Đếm ba hai một xong mình đọc rõ câu nhé!', NULL, 'draft', NOW()),
('DN-F04-TG-03', 'F-04', 'TG', 'Storm bảo chỉ cần nói to, rõ nhịp là vượt gió Tháp Gió dễ ợt! Cùng Cowdi luyện nói từng câu nha!', NULL, 'draft', NOW()),
('DN-F04-TG-04', 'F-04', 'TG', 'Cánh quạt Tháp Gió quay đều theo giọng đọc của con kìa! Nghe mẫu chậm nếu cần rồi đọc lại nhé!', NULL, 'draft', NOW()),
('DN-F04-VS-01', 'F-04', 'VS', 'Giữa Vườn Sữa yên tĩnh, con nghe mẫu rồi đọc to giúp pet nhảy qua từng tảng đá nhé!', NULL, 'draft', NOW()),
('DN-F04-VS-02', 'F-04', 'VS', 'Bamboo đứng bên rừng trúc Vườn Sữa cổ vũ con nói tiếng Anh thật tự tin! Đếm xong mình đọc nha!', NULL, 'draft', NOW()),
('DN-F04-VS-03', 'F-04', 'VS', 'Đàn gà ở Vườn Sữa im lặng lắng nghe con phát âm rồi! Nghe kỹ câu mẫu rồi đọc theo cùng bò nhé!', NULL, 'draft', NOW()),
('DN-F04-VS-04', 'F-04', 'VS', 'Bamboo Spirit dẫn lối qua dòng suối nhỏ ở Vườn Sữa. Con đọc rõ từng câu giúp Cowdi vượt qua nha!', NULL, 'draft', NOW()),
('DN-F05-BD-01', 'F-05', 'BD', 'Sương sớm Bến Đò Ông Tư che mất vài từ trong đoạn văn rồi! Nghe từ rồi chạm đúng ô sương nha!', NULL, 'draft', NOW()),
('DN-F05-BD-02', 'F-05', 'BD', 'Ông Tư nhờ con tìm các từ ẩn trong làn sương trên bến gỗ. Sương tan hết mình trả lời câu hỏi nhé!', NULL, 'draft', NOW()),
('DN-F05-BD-03', 'F-05', 'BD', 'Mặt sông sang Cù Lao bảng lảng sương mù. Con nghe kỹ từng từ rồi chạm giải sương cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F05-BD-04', 'F-05', 'BD', 'Mỗi lần chạm đúng từ khóa là màn sương Bến Đò mỏng đi hẳn. Cùng bò săn chữ rồi đọc hiểu nhé!', NULL, 'draft', NOW()),
('DN-F05-TG-01', 'F-05', 'TG', 'Làn gió Tháp Gió cuốn sương che mất mấy từ khóa trong bài đọc! Con nghe rồi chạm mở chữ nha!', NULL, 'draft', NOW()),
('DN-F05-TG-02', 'F-05', 'TG', 'Owlbert đánh dấu sẵn các ô sương tại Tháp Gió. Con nghe phát âm rồi tìm đúng vị trí từ cùng bò nhé!', NULL, 'draft', NOW()),
('DN-F05-TG-03', 'F-05', 'TG', 'Mimi bảo tìm hết từ khóa trong sương xong mình đọc bản dịch rất dễ hiểu! Bắt đầu cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F05-TG-04', 'F-05', 'TG', 'Storm quét bớt mây trên cánh đồng Tháp Gió, còn các ô sương trong đoạn văn nhờ con mở hết nhé!', NULL, 'draft', NOW()),
('DN-F05-VS-01', 'F-05', 'VS', 'Vườn Sữa sáng nay có vài cụm sương che mất từ khóa trong bài đọc. Nghe từ rồi chạm mở cùng bò nha!', NULL, 'draft', NOW()),
('DN-F05-VS-02', 'F-05', 'VS', 'Bamboo giấu vài từ mới sau lớp sương bên rừng trúc Vườn Sữa. Con nghe kỹ rồi tìm đúng ô chữ nhé!', NULL, 'draft', NOW()),
('DN-F05-VS-03', 'F-05', 'VS', 'Đàn gà ở Vườn Sữa thích xem con giải sương cho đoạn văn lắm! Mở hết từ rồi trả lời hai câu nha!', NULL, 'draft', NOW()),
('DN-F05-VS-04', 'F-05', 'VS', 'Cowdi và Bamboo Spirit cùng con săn từ khóa tại Vườn Sữa. Chạm đúng ô sương để chữ sáng vàng nhé!', NULL, 'draft', NOW());
